import java.nio.file.*;import java.util.*;import java.lang.reflect.*;import org.json.*;
public final class PlaymogoSmokeTest {
 public static void main(String[] args)throws Exception{JSONArray fixtures=new JSONObject(new String(Files.readAllBytes(Paths.get(args[0])),"UTF-8")).getJSONArray("fixtures"),results=new JSONArray();int pass=0;for(int i=0;i<fixtures.length();i++){JSONObject f=fixtures.getJSONObject(i),out=new JSONObject().put("title",f.getString("title"));long start=System.nanoTime();NativeHttp.CURRENT.set(new NativeHttp.Session(35000));try{DozaCatalog.Located located=new DozaCatalog().locate(f.getJSONObject("data"));if(located==null||!located.pageUrl.equals(f.getString("page")))throw new Exception("Wrong or missing episode address");List<NativeCatalog.Candidate> found=DozaCatalog.players(located);JSONArray hosts=new JSONArray();NativeCatalog.Candidate selected=null;for(NativeCatalog.Candidate c:found){hosts.put(c.host);if(c.host.equals("Playmogo"))selected=c;}if(selected==null||!selected.embed.equals(f.getString("expectedPlaymogo")))throw new Exception("Wrong Playmogo embed");ResolvedStream stream=RoDubbedProvider.resolve(selected);Object link=RoDubbedProvider.makeLink(stream);Map headers=(Map)link.getClass().getMethod("getHeaders").invoke(link);if(!link.getClass().getMethod("getType").invoke(link).toString().equals("VIDEO")||headers.containsKey("Origin"))throw new Exception("Incorrect native link type/headers");
  Class<?> type=Class.forName("android.media.MediaMetadataRetriever");Object retriever=type.getConstructor().newInstance();try{type.getMethod("setDataSource",String.class,Map.class).invoke(retriever,stream.url,headers);Method meta=type.getMethod("extractMetadata",int.class);long duration=Long.parseLong((String)meta.invoke(retriever,9));if(duration<90000||!"yes".equals(meta.invoke(retriever,16))||!"yes".equals(meta.invoke(retriever,17)))throw new Exception("Full audio/video missing");long a=AbyssSmokeTest.frame(retriever,30000000),b=AbyssSmokeTest.frame(retriever,60000000);if(a==b)throw new Exception("Identical distant frames");out.put("addressPass",true).put("supportedHosts",hosts).put("durationMs",duration).put("decodedFrames",2).put("pass",true);pass++;}finally{type.getMethod("release").invoke(retriever);}
 }catch(Throwable e){Throwable cause=e instanceof InvocationTargetException?((InvocationTargetException)e).getCause():e;out.put("pass",false).put("error",cause.toString());}finally{NativeHttp.session().stop();NativeHttp.CURRENT.remove();}out.put("ms",(System.nanoTime()-start)/1000000);results.put(out);System.out.println(out);}Files.write(Paths.get(args[1]),new JSONObject().put("passed",pass).put("total",fixtures.length()).put("results",results).toString(2).getBytes("UTF-8"));System.exit(pass==fixtures.length()?0:1);}
}
